@Test
void testConnectAll_disjointPaths_1_oe() {
    runWithMaxAndMin(connector -> {
        // arrange
        final List<LineConvexSubset> segments = new ArrayList<>(createSquare(Vector2D.ZERO, 1, 1));

        final Vector2D pt = Vector2D.of(0, 2);
        final ReverseRay a = Lines.fromPointAndAngle(pt, 0.0, TEST_PRECISION).reverseRayTo(pt);
        final Ray b = Lines.fromPointAndAngle(pt, Angle.PI_OVER_TWO, TEST_PRECISION).rayFrom(pt);

        segments.add(a);
        segments.add(b);

        shuffle(segments);

        // act
        final List<LinePath> paths = connector.connectAll(segments);

        // assert
        Assertions.assertEquals(2, paths.size());
}
}

@Test
void testCreateRotationVector_1_oe() {
    // arrange
    final double min = -8;
    final double max = 8;
    final double step = 1;

    EuclideanTestUtils.permuteSkipZero(min, max, step, (ux, uy) -> {
        EuclideanTestUtils.permuteSkipZero(min, max, step, (vx, vy) -> {

            final Vector2D u = Vector2D.of(ux, uy);
            final Vector2D v = Vector2D.of(vx, vy);

            // act
            final Rotation2D r = Rotation2D.createVectorRotation(u, v);

            // assert
            EuclideanTestUtils.assertCoordinatesEqual(v.normalize(), r.apply(u).normalize(), TEST_EPS); // u -> v
            Assertions.assertEquals(0.0, v.dot(r.apply(u.orthogonal())), TEST_EPS); // preserves orthogonality;
}
}
}

