    final Vector3D p1 = plane.project(Vector3D.of(4, 5, 6));
    final Vector3D p2 = plane.project(Vector3D.of(-7, -8, -9));
    final Vector3D p3 = plane.project(Vector3D.of(10, -11, 12));

    final Vector3D notOnPlane1 = plane.getOrigin().add(plane.getNormal());
    final Vector3D notOnPlane2 = plane.getOrigin().subtract(plane.getNormal());

    EuclideanTestUtils.permuteSkipZero(-4, 4, 1, (a, b, c) -> {
        final AffineTransformMatrix3D t = AffineTransformMatrix3D.identity()
                .rotate(Vector3D.of(-1, 2, 3),
                        QuaternionRotation.fromAxisAngle(Vector3D.Unit.PLUS_X, 0.3 * a))
                .scale(Math.max(a, 1), Math.max(b, 1), Math.max(c, 1))
                .translate(c, b, a);

        // act
        final EmbeddingPlane result = plane.transform(t);

        // assert
        Vector3D expectedNormal = t.normalTransform().apply(plane.getNormal()).normalize();
        if (!t.preservesOrientation()) {
            expectedNormal = expectedNormal.negate();
        }

        EuclideanTestUtils.assertCoordinatesEqual(expectedNormal, result.getNormal(), TEST_EPS);

        // removed other assertion
        // removed other assertion
        // removed other assertion

        // removed other assertion
        Assertions.assertFalse(result.contains(t.apply(notOnPlane2)));
}
}

@Test
void testExtrudeVertexLoop_regionsConsistentBetweenExtrusionPlanes_1_oe() {
    // arrange
    final List<Vector2D> vertices = Arrays.asList(
            Vector2D.of(1, 2),
            Vector2D.of(1, -2),
            Vector2D.of(4, -2),
            Vector2D.of(4, -1),
            Vector2D.of(2, -1),
            Vector2D.of(2, 1),
            Vector2D.of(4, 1),
            Vector2D.of(4, 2),
            Vector2D.of(1, 2)
        );

    final RegionBSPTree2D subspaceTree = LinePath.fromVertexLoop(vertices, TEST_PRECISION).toTree();

    final double subspaceSize = subspaceTree.getSize();
    final Vector2D subspaceCentroid = subspaceTree.getCentroid();

    final double extrusionLength = 2;
    final double expectedSize = subspaceSize * extrusionLength;

    final Vector3D planePt = Vector3D.of(-1, 2, -3);

    EuclideanTestUtils.permuteSkipZero(-2, 2, 1, (x, y, z) -> {
        final Vector3D normal = Vector3D.of(x, y, z);
        final EmbeddingPlane plane = Planes.fromPointAndNormal(planePt, normal, TEST_PRECISION).getEmbedding();

        final Vector3D baseCentroid = plane.toSpace(subspaceCentroid);

        final Vector3D plusExtrusionVector = normal.withNorm(extrusionLength);
        final Vector3D minusExtrusionVector = plusExtrusionVector.negate();

        // act
        final RegionBSPTree3D extrudePlus = RegionBSPTree3D.from(
                Planes.extrudeVertexLoop(vertices, plane, plusExtrusionVector, TEST_PRECISION));
        final RegionBSPTree3D extrudeMinus = RegionBSPTree3D.from(
                Planes.extrudeVertexLoop(vertices, plane, minusExtrusionVector, TEST_PRECISION));

        // assert
        Assertions.assertEquals(expectedSize, extrudePlus.getSize(), TEST_EPS);
}
}

